text:
This observatory gathers public inequality indicators for European and world countries. The data are downloaded live from the official sources every time the page is opened, so they always show the latest release. Each chart can be explored by hovering over the points, and the data can be downloaded as CSV.
Code
function jsonstat(js) {
  // Flattens a JSON-stat 2.0 dataset (Eurostat API) into an array of records
  const ids = js.id, size = js.size, dims = js.dimension;
  const codes = ids.map(d =&gt; {
    const idx = dims[d].category.index;
    const arr = Array.isArray(idx) ? idx : Object.keys(idx).sort((a, b) =&gt; idx[a] - idx[b]);
    return arr;
  });
  const labels = ids.map(d =&gt; dims[d].category.label || {});
  const out = [];
  const vals = js.value;
  const keys = Array.isArray(vals) ? vals.map((v, i) =&gt; i).filter(i =&gt; vals[i] != null) : Object.keys(vals).map(Number);
  for (const i of keys) {
    let rem = i; const rec = {};
    for (let d = ids.length - 1; d &gt;= 0; d--) {
      const c = codes[d][rem % size[d]];
      rec[ids[d]] = c;
      if (ids[d] === "geo") rec.country = labels[d][c] || c;
      rem = Math.floor(rem / size[d]);
    }
    rec.value = +vals[i];
    out.push(rec);
  }
  return out;
}
pref = ["TOTAL", "T", "SHARE", "EUR", "PC", "A"]
function keepPreferred(recs, keepDims) {
  // For dimensions other than geo/time (and keepDims) keep a single category
  if (!recs.length) return recs;
  const dimsAll = Object.keys(recs[0]).filter(k =&gt; !["geo", "time", "value", "country", ...keepDims].includes(k));
  let r = recs;
  for (const d of dimsAll) {
    const cats = [...new Set(r.map(x =&gt; x[d]))];
    const chosen = pref.find(p =&gt; cats.includes(p)) ?? cats[0];
    r = r.filter(x =&gt; x[d] === chosen);
  }
  return r;
}
async function eurostat(code, query = "") {
  const url = `https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/${code}?format=JSON&lang=EN${query}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Eurostat ${code}: HTTP ${res.status}`);
  return jsonstat(await res.json());
}
EU = new Set(["AT","BE","BG","CY","CZ","DE","DK","EE","EL","ES","FI","FR","HR","HU","IE","IT","LT","LU","LV","MT","NL","PL","PT","RO","SE","SI","SK","EU27_2020","NO","CH","IS","RS","TR","MK","ME","AL"])
Code
// ---------- Download Eurostat data ----------
euroData = {
  try {
    const [gini, s80, dec] = await Promise.all([
      eurostat("ilc_di12"),
      eurostat("ilc_di11"),
      eurostat("ilc_di01", "&indic_il=SHARE" + ["D1","D2","D3","D4","D5","D6","D7","D8","D9","D10"].map(q =&gt; `&quantile=${q}`).join(""))
    ]);
    const rows = [];
    for (const r of keepPreferred(gini, [])) rows.push({geo: r.geo, country: r.country, year: +r.time, indicator: "Gini index", value: r.value});
    for (const r of keepPreferred(s80, [])) rows.push({geo: r.geo, country: r.country, year: +r.time, indicator: "S80/S20 ratio", value: r.value});
    // Theil approximations from decile shares (grouped data, lower bound)
    const d = keepPreferred(dec, ["quantile"]);
    const groups = d3.group(d, r =&gt; r.geo, r =&gt; r.time);
    for (const [geo, byYear] of groups) for (const [time, recs] of byYear) {
      if (recs.length !== 10) continue;
      const tot = d3.sum(recs, r =&gt; r.value);
      const s = recs.map(r =&gt; r.value / tot).filter(v =&gt; v &gt; 0);
      if (s.length !== 10) continue;
      const T1 = d3.sum(s, v =&gt; v * Math.log(10 * v));
      const T0 = d3.sum(s, v =&gt; 0.1 * Math.log(0.1 / v));
      rows.push({geo, country: recs[0].country, year: +time, indicator: "Theil T1 (decile approx.)", value: T1});
      rows.push({geo, country: recs[0].country, year: +time, indicator: "Theil T0 (decile approx.)", value: T0});
    }
    return {ok: true, rows: rows.filter(r =&gt; EU.has(r.geo) && Number.isFinite(r.value))};
  } catch (e) {
    return {ok: false, error: e.message, rows: []};
  }
}

